use tauri::Runtime;

use crate::models::{PingRequest, PingResponse};

/// Echo command used as a smoke-test of the plugin IPC pipeline.
///
/// Replace this with your plugin's actual commands. Remember to add each new
/// command name to the `COMMANDS` array in `build.rs` so the autogenerated
/// `allow-<cmd>` / `deny-<cmd>` permissions are created.
#[tauri::command]
pub async fn ping<R: Runtime>(
    _app: tauri::AppHandle<R>,
    request: PingRequest,
) -> crate::Result<PingResponse> {
    Ok(PingResponse {
        value: request.value,
    })
}
